Here are a variety of approaches:

``` java
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.concurrent.TimeUnit;

import rx.Observable;
import rx.exceptions.OnErrorThrowable;
import rx.subjects.PublishSubject;

public class ScanErrorExample {

    public static void main(String... args) {
        System.out.println("scanWithErrorThrownAndDropped -------------------------------");
        scanWithErrorThrownAndDropped();
        System.out.println("scanWithErrorThrownAndLogged -------------------------------");
        scanWithErrorThrownAndLogged();
        System.out.println("scanWithErrorEvent -------------------------------");
        scanWithErrorEvent();
        System.out.println("scanWithFilteredData -------------------------------");
        scanWithFilteredData();
        System.out.println("-------------------------------");
    }

    public static void scanWithErrorThrownAndDropped() {
        data()
                .map(time -> {
                    if (time.endsWith("5")) {
                        throw OnErrorThrowable.from(new Exception("wow"));
                    } else {
                        return time;
                    }
                })
                .retry()
                .scan("", (times, time) -> {
                    return times + "," + time;
                })
                .take(15)
                .toBlocking().forEach(System.out::println);
    }

    public static void scanWithErrorThrownAndLogged() {
        data()
                .map(time -> {
                    if (time.endsWith("5")) {
                        throw OnErrorThrowable.from(new Exception("wow"));
                    } else {
                        return time;
                    }
                })
                .doOnError(e -> System.out.println("Error: " + e))
                .retry()
                .scan("", (times, time) -> {
                    return times + "," + time;
                })
                .take(15)
                .toBlocking().forEach(System.out::println);
    }

    public static void scanWithErrorEvent() {
        PublishSubject<Exception> errors = PublishSubject.create();
        errors.forEach(e -> System.out.println("Error: " + e));

        data()
                .doOnNext(time -> {
                    if (time.endsWith("5")) {
                        errors.onNext(new Exception("wow"));
                        // or just log them
                    }
                })
                .filter(time -> !time.endsWith("5"))
                .retry()
                .scan("", (times, time) -> {
                    return times + "," + time;
                })
                .take(15)
                .toBlocking().forEach(System.out::println);
    }

    public static void scanWithFilteredData() {
        data()
                .filter(time -> !time.endsWith("5"))
                .scan("", (times, time) -> {
                    return times + "," + time;
                })
                .take(15)
                .toBlocking().forEach(System.out::println);
    }

    public static Observable<String> data() {
        return Observable.interval(1, TimeUnit.SECONDS)
                .map(i -> {
                    Calendar cal = Calendar.getInstance();
                    cal.getTime();
                    SimpleDateFormat sdf = new SimpleDateFormat("HH:mm:ss");
                    return sdf.format(cal.getTime());
                });
    }

}
```

If you need the error data inside the scan as well, then instead of throwing, convert it to a type that you treat as an event that your scan logic can understand.

