Here are some options that might get you moving in the direction you want:

``` java
import java.util.concurrent.TimeUnit;

import rx.Observable;

public class CombineLatestAndFilter {

    public static void main(String[] args) {
        Observable<String> observable1 = Observable.interval(1, TimeUnit.MILLISECONDS).map(i -> "value_" + i);
        Observable<Boolean> observable2 = Observable.interval(7, TimeUnit.MILLISECONDS).map(i -> i % 2 == 0 ? true : false).startWith(false);

        /*
         * Solution A
         * 
         * This works as long as you're okay if the last observable1 value is emitted when observable2 changes from false to true
         */
        Observable<String> observable3a = Observable.combineLatest(observable1, observable2, (o1, o2) -> {
            System.out.println("        o1: " + o1 + " o2: " + o2);
            return new Object[] { o1, o2 }; // poor excuse for a tuple
            }).filter(oo -> (Boolean) oo[1]).map(oo -> (String) oo[0]);

        /*
         * Solution B
         * 
         * This adds 'distinctUntilChanged' so that it won't emit during the change from false -> true.
         * However, this means it could also skip values from observable1 if duplicates are expected, so it can only be used if
         * the values are expected to be unique.
         */
        Observable<String> observable3b = Observable.combineLatest(observable1, observable2, (o1, o2) -> {
            System.out.println("        o1: " + o1 + " o2: " + o2);
            return new Object[] { o1, o2 }; // poor excuse for a tuple
            }).distinctUntilChanged(oo -> (String) oo[0]).filter(oo -> (Boolean) oo[1]).map(oo -> (String) oo[0]);

        /*
         * Solution C
         * 
         * This gets more complicated by zipping observable1 with a range to index it so we can de-dupe on the index number
         * instead of the value in case we need to handle possible duplicate values and solution A above is not okay.
         */
        Observable<Object[]> observable1withIndex = observable1.zipWith(Observable.range(0, Integer.MAX_VALUE), (v, i) -> new Object[] { v, i });
        Observable<String> observable3c = Observable.combineLatest(observable1withIndex, observable2, (o1, o2) -> {
            System.out.println("        o1: " + o1[0] + " index: " + o1[1] + " o2: " + o2);
            return new Object[] { o1[1], "repetitive-value", o2 }; // poor excuse for a tuple
            }).distinctUntilChanged(oo -> oo[0]).filter(oo -> (Boolean) oo[2]).map(oo -> (String) oo[1]);

        observable3a.take(20).toBlocking().forEach(System.out::println);
        //        observable3b.take(20).toBlocking().forEach(System.out::println);
        //        observable3c.take(20).toBlocking().forEach(System.out::println);
    }
}
```
